import type {CanonicalProvenance,CanonicalRule} from "../data-layer-canonical-schema.js";
export const clone=<T>(value:T):T=>structuredClone(value);
export const semanticallyPopulated=(value:unknown):boolean=>{if(value===undefined||value===null)return false;if(Array.isArray(value))return value.some(semanticallyPopulated);if(typeof value==="string")return value.trim().length>0;if(typeof value!=="object")return true;return Object.entries(value as Record<string,unknown>).some(([key,entry])=>{if(key==="type"&&entry==="object")return false;if(key==="properties"&&entry&&typeof entry==="object"&&!Array.isArray(entry))return Object.keys(entry as Record<string,unknown>).length>0;return semanticallyPopulated(entry);});};
export type DefinitionEntry={definition:Record<string,unknown>;provenance:CanonicalProvenance};
export const definitionAtPath=(definitions:Map<string,DefinitionEntry[]>,path:string,definition:Record<string,unknown>,provenance:CanonicalProvenance):void=>{const values=definitions.get(path)??[];values.push({definition,provenance});definitions.set(path,values);};
export const collectStructured=(definitions:Map<string,DefinitionEntry[]>,document:Record<string,unknown>,source:CanonicalProvenance["source"],parent=""):void=>{const properties=document.properties as Record<string,Record<string,unknown>>|undefined,required=new Set((document.required as string[]|undefined)??[]);for(const[name,definition]of Object.entries(properties??{})){const path=`${parent}/${name}`,normalized=required.has(name)?{...definition,required:true}:definition;definitionAtPath(definitions,path,normalized,{source});if(definition.type==="array"&&definition.items&&typeof definition.items==="object"){let items=definition.items as Record<string,unknown>;while(items.type==="array"&&items.items&&typeof items.items==="object")items=items.items as Record<string,unknown>;if(items.type==="object"||items.properties)collectStructured(definitions,items,source,path);}else if(definition.type==="object"||definition.properties)collectStructured(definitions,definition,source,path);}};
export const explicitValues=<T>(defs:DefinitionEntry[],read:(definition:Record<string,unknown>)=>T|undefined):{value:T;sources:string[]}[]=>{const values:{value:T;sources:string[]}[]=[];for(const{definition,provenance}of defs){const value=read(definition);if(value===undefined)continue;const prior=values.find((candidate)=>JSON.stringify(candidate.value)===JSON.stringify(value));if(prior)prior.sources.push(provenance.source);else values.push({value:clone(value),sources:[provenance.source]});}return values;};
export const canonicalRules=(definition:Record<string,unknown>,path:string,source:string,profileId:string):CanonicalRule[]=>{const given=((definition.rules??definition["x-rules"]) as CanonicalRule[]|undefined)??[],patterns=[...(definition.patterns as string[]|undefined)??[],...(typeof definition.pattern==="string"?[definition.pattern]:[])],facetId=(kind:string,index?:number)=>`json-facet:${profileId}:${encodeURIComponent(path)}:${source}:${kind}${index===undefined?"":`:${index}`}`,range=definition.minimum!==undefined||definition.maximum!==undefined?[{id:facetId("range"),kind:"range" as const,severity:"error" as const,message:"Outside migrated range",...(typeof definition.minimum==="number"?{minimum:definition.minimum}:{}),...(typeof definition.maximum==="number"?{maximum:definition.maximum}:{})}]:[],cardinality=definition.minItems!==undefined||definition.maxItems!==undefined?[{id:facetId("cardinality"),kind:"cardinality" as const,severity:"error" as const,message:"Outside migrated cardinality",...(typeof definition.minItems==="number"?{minItems:definition.minItems}:{}),...(typeof definition.maxItems==="number"?{maxItems:definition.maxItems}:{})}]:[];return[...given.map(clone),...patterns.map((pattern,index)=>({id:facetId("pattern",index),kind:"pattern" as const,pattern,severity:"error" as const,message:"Pattern mismatch"})),...range,...cardinality];};
